<?php
require_once __DIR__ . '/../app/bootstrap.php';
require_once __DIR__ . '/../app/layout.php';
$user=require_role(['student']);
$hasFeedback=codearena_table_exists($pdo,'submission_feedback');
$feedbackJoin=$hasFeedback?'LEFT JOIN submission_feedback sf ON sf.submission_id=s.id AND sf.teacher_id=e.created_by':'';
$feedbackCols=$hasFeedback?'sf.feedback_text,sf.feedback_type,sf.updated_at AS feedback_updated_at':'NULL AS feedback_text,NULL AS feedback_type,NULL AS feedback_updated_at';
$hasRegradeHistory=codearena_table_exists($pdo,'submission_regrade_history');
$regradeJoin=$hasRegradeHistory?'LEFT JOIN (SELECT submission_id,COUNT(*) AS regrade_count,MAX(regraded_at) AS last_regraded_at FROM submission_regrade_history GROUP BY submission_id) rh ON rh.submission_id=s.id':'';
$regradeCols=$hasRegradeHistory?'COALESCE(rh.regrade_count,0) AS regrade_count,rh.last_regraded_at':'0 AS regrade_count,NULL AS last_regraded_at';
$sql="SELECT s.id,s.exercise_id,s.language,s.score,s.passed_tests,s.total_tests,s.created_at,e.title,e.points AS current_points,ev.snapshot_json,ev.version_number,{$feedbackCols},{$regradeCols}
FROM submissions s JOIN exercises e ON e.id=s.exercise_id LEFT JOIN exercise_versions ev ON ev.id=s.exercise_version_id {$feedbackJoin} {$regradeJoin}
WHERE s.user_id=? ORDER BY s.created_at DESC LIMIT 200";
$stmt=$pdo->prepare($sql);$stmt->execute([(int)$user['id']]);$rows=$stmt->fetchAll();
foreach($rows as &$r){$r['max_points']=max(1,(int)$r['current_points']);if(!empty($r['snapshot_json'])){$snap=json_decode((string)$r['snapshot_json'],true);if(is_array($snap['exercise']??null)){$r['title']=(string)($snap['exercise']['title']??$r['title']);$r['max_points']=max(1,(int)($snap['exercise']['points']??$r['max_points']));}}}unset($r);
page_header('Submission history');
?>
<section class="page-hero compact-page-hero"><div><p class="eyebrow">STUDENT SPACE · HISTORY</p><h1>Your submission history</h1><p class="muted">Review saved scores, language, timestamps, and teacher feedback.</p></div><div class="page-hero-actions"><a class="button" href="<?= e($config['base_url']) ?>/index.php#practice">Practice Arena ↗</a></div></section>
<?php if(!$rows): ?><div class="empty"><div class="empty-symbol">⌁</div><h3>No submissions yet</h3><p>Your graded programming submissions will appear here. Practice-only runs remain separate from official grades.</p><a class="button" href="<?= e($config['base_url']) ?>/student-classrooms.php">Open My Classes</a></div><?php else: ?><div class="v23-submission-history"><?php foreach($rows as $r):$pct=(int)round((int)$r['score']/$r['max_points']*100); ?><article class="panel v23-submission-history-card"><div class="v23-submission-history-head"><div><span class="pill"><?= e(strtoupper((string)$r['language'])) ?></span><h2><?= e($r['title']) ?></h2><small class="muted"><?= e(date('M j, Y · g:i A',strtotime((string)$r['created_at']))) ?><?= !empty($r['version_number'])?' · Version '.(int)$r['version_number']:'' ?></small><?php if((int)($r['regrade_count']??0)>0): ?><small class="v23-regraded-marker">Regraded <?= (int)$r['regrade_count'] ?> time<?= (int)$r['regrade_count']===1?'':'s' ?> · latest <?= e(date('M j, Y · g:i A',strtotime((string)$r['last_regraded_at']))) ?></small><?php endif; ?></div><div class="v23-submission-score <?= $pct>=100?'score-green':($pct>=50?'score-amber':'score-red') ?>"><strong><?= (int)$r['score'] ?>/<?= (int)$r['max_points'] ?></strong><small><?= $pct ?>% · <?= (int)$r['passed_tests'] ?>/<?= (int)$r['total_tests'] ?> tests</small></div></div><?php if(!empty($r['feedback_text'])):?><div class="v23-student-feedback"><div class="v23-feedback-title"><strong>Teacher feedback</strong><span class="pill <?= $r['feedback_type']==='approved'?'pill-success':($r['feedback_type']==='needs_revision'?'pill-warning':'pill-info') ?>"><?= e(str_replace('_',' ',$r['feedback_type'])) ?></span></div><p><?= nl2br(e($r['feedback_text'])) ?></p><small class="muted">Updated <?= e(date('M j, Y · g:i A',strtotime((string)$r['feedback_updated_at']))) ?></small></div><?php else: ?><p class="muted v23-no-feedback">No teacher feedback on this submission yet.</p><?php endif; ?><a class="quiet-link" href="<?= e($config['base_url']) ?>/exercise.php?id=<?= (int)$r['exercise_id'] ?>">Open exercise / review latest result →</a></article><?php endforeach; ?></div><?php endif; ?>
<?php page_footer(); ?>
